--
-- Структура таблицы `texts`
--

CREATE TABLE `texts` (
  `id_text` int(11) NOT NULL,
  `text_field_ref` int(11) NOT NULL,
  `text_type_ref` int(11) NOT NULL,
  `value` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `field_text_type` varchar(255) COLLATE utf8mb4_unicode_ci GENERATED ALWAYS AS (concat(`text_field_ref`,_utf8mb4'_',`text_type_ref`)) VIRTUAL NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Дамп данных таблицы `texts`
--

INSERT INTO `texts` (`id_text`, `text_field_ref`, `text_type_ref`, `value`) VALUES
(4833, 103, 1, 'Такси из Симферополя  заказать по  тел. [phone]. Сколько стоит такси  Симферополь. У нас вы можете заказать подачу автомобиля в любую точку  Симферополя. Быстро и безопасно - вот наш девиз!'),
(4834, 104, 1, 'Такси по Крыму. Такси Симферополь'),
(4835, 105, 1, 'ТАКСИ ПО КРЫМУ. ТАКСИ СИМФЕРОПОЛЬ АЭРОПОРТ'),
(4836, 106, 1, 'НАДЕЖНОЕ И ДОСТУПНОЕ ТАКСИ ПО СТОИМОСТИ НА 20% НИЖЕ РЫНОЧНЫХ ЦЕН.'),
(4837, 107, 1, 'Посмотреть прайс лист'),
(4838, 108, 1, 'Заказать точный рассчет стоимости поездки'),
(4839, 109, 1, '<span>О нас</span>'),
(4840, 110, 1, 'НЕДОРОГОЕ ТАКСИ ИЗ СИМФЕРОПОЛЯ ПО КРЫМУ'),
(4841, 111, 1, 'Недорого закажите такси по Крыму из Симферополя'),
(4842, 112, 1, '<p>Такси  из Симферополя по Крыму заказать и узнать цену можно узнать по тел. [phone] или на официальном сайте. \r\nСпрос на поездки по Крыму высокий в любое время, особенно в курортный период. Часто,\r\nзаказывая такси в Симферополь, клиент слышит, что свободных машин нет. Это неприятное\r\nобстоятельство срывает все планы. Обращаясь в компанию по перевозкам, человек может\r\nрассчитывать на быстрое и качественное обслуживание. Автопарк фирмы достаточно большой и\r\nразнообразный, поэтому заказать поездку можно от эконом класса до минибуса на 8 человек. На сайте\r\nесть вся актуальная информация о ценах и классах машин.</p>'),
(4843, 113, 1, '<p>1. Быстрое и качественное обслуживание. Фирма предоставляет возможность заказа на\r\nофициальном сайте и с помощью телефонного звонка. Каждый выбирает удобный для\r\nсебя способ, а диспетчер мгновенно реагирует на заявку независимо от выбранного\r\nметода заказа такси.</p>\r\n<p>2. Комфортные автомобили. Машины в автопарке рассчитаны даже на большое количество\r\nлюдей. Для компании из 8 человек приезжает просторный мини-бус. Также клиент может\r\nвыбрать такси из Симферополя на любой кошелек. Есть более дешевые и дорогие варианты\r\n(эконом, комфорт, бизнес).</p>\r\n<p>3. Работаем в любое время суток. Скорость работы оператора и водителя не зависит от времени\r\nсуток, в которое поступил заказ. Заявка будет обработана одинаково быстро как днем, так\r\nи ночью.</p>\r\n<p>4. Регулярные скидки. На официальном сайте указывается актуальная информация, в том\r\nчисле и размер постоянных скидок. Сейчас действуют акции, помогающие значительно\r\nсэкономить средства. Детские кресла или ФЭСТ предоставляются бесплатно по\r\nнеобходимости.</p>\r\n<p>Машины компании порадуют клиента не только безопасностью, но и стильным видом, а также\r\nчистотой салона. Такси из Симферополя эконом класса по внешнему виду ненамного уступает бизнес\r\nклассу, поэтому клиент с небольшим бюджетом с комфортом проведет поездку. Понравившийся\r\nавтомобиль можно забронировать заранее. Он будет ожидать  клиента в назначенном\r\nместе и времени.</p>'),
(4844, 114, 1, 'Тарифы такси из Симферополя <span>по Крыму</span>'),
