(4864, 138, 1, 'Время отъезда изменилось, что делать?'),
(4865, 139, 1, 'В случае изменения времени отъезда, вам необходимо дополнительно сообщить об этом диспетчеру нашей компании. Подача автомобиля будет скорректирована с учетом реального времени прилета.'),
(4866, 140, 1, 'Откуда я могу узнать, какая будет машина и телефон водителя?'),
(4867, 141, 1, 'Перед поездкой на указанный вами номер телефона поступит СМС сообщение, где будет указана марка автомобиля, гос.номер, контактный телефон водителя. А также, в обязанности водителя входит то, что он должен сам созвониться с пассажирами после приземления самолета.'),
(4868, 142, 1, 'Та цена, которую мне сказали окончательная? Доплат не будет?'),
(4869, 143, 1, 'Стоимость проезда, которую вам озвучил диспетчер или указал менеджер в письме фиксированная. Доплата, может быть, только в случае существенного изменения вашего маршрута.'),
(4870, 144, 1, 'Как надежнее: сделать заказ через форму заказа на сайте или по телефону? За какое время нужно заказать автомобиль?'),
(4871, 145, 1, 'Любой из выбранных способов надежный. Диспетчер, в любое время суток может принять Ваш заказ по телефону и сразу забронировать автомобиль. При бронировании через форму заказа на сайте, менеджер в ближайшее время, после поступления вашего письма, ответит вам на ваш запрос. В обоих случаях, без автомобиля вы не останетесь. Сделать заказ можно в любое время. Мы рекомендуем забронировать такси за 1-2 суток поездки.'),
(4872, 146, 1, 'Такси из Симферополя отзывы'),
(4873, 147, 1, 'Светлана'),
(4874, 148, 1, 'Я очень довольна сервисом компании, по прилёту меня сразу же встретили в аэропорту Симферополя с табличкой и помогли с багажом при этом без доплаты. Водитель был очень вежлив, а салон был чистым и с приятным легким запахом. Я доехала спокойно и с удовольствием. Всем рекомендую!'),
(4875, 149, 1, 'Такси в Симферополь отзывы'),
(4876, 150, 1, 'Валентин'),
(4877, 151, 1, 'Заказывал через сайт такси бизнес класса за час до вылета. Не смотря на то что самолёт задержали меня ждали до последнего, встретили в самом аэропорту Симферополя и мне не пришлось некого искать. Подали Toyota Camry со всеми удобствами и комфортом всё как полагается. Доехал я быстро и в приятной компании. Буду Вашим постоянным клиентом.'),
(4878, 152, 1, 'Такси в Симферополь отзывы'),
(4879, 153, 1, 'Вячеслав'),
(4880, 154, 1, 'Пользуюсь услугами Вашего такси уже более 3-х лет по работе в командировке. Выбрав случайно один раз, оставив заявку на сайте и мне перезвонили буквально через 5 минут сориентировали по цене и другим вопросам. Ну и что скажу по сервису - встретили, помогли с багажом, приятные и тактичные водители. Теперь всегда пользуюсь их услугами так как всё устраивает. Советую данную компанию.'),
(4881, 155, 1, 'О нас говорят <span>наши клиенты</span>'),
(4882, 156, 1, 'Описание'),
(4883, 157, 1, '<p>Такси в Симферополь онлайн.  Заказать и узнать цену из Симферополя по Крыму можно узнать по телефону <nobr>[phone]</nobr></p>'),
(4884, 158, 1, '© Симферополь [year] Симферополь'),
(4885, 159, 1, 'Политика конфиденциальности и оферты'),
(4886, 160, 1, '<p>Нам очень важна конфиденциальность Вашей информации. Личные данные, которые Вы доверяете нам, заполняя форму заявки на нашем сайте, будут использованы с целью подготовки услуг в соответствии с Вашими основными требованиями и пожеланиями. Передача Вашей информации третьим лицам полностью исключена. Какие данные собираются на сайте: При добровольном заполнении формы заявки Вы отправляете нам: свое имя, телефон и E-mail. Наш сайт не является публичной офертой и носит исключительно информационный характер </p>'),
(4887, 161, 1, 'Такси По Крыму из Симферополя'),
(4888, 162, 1, 'читать подробнее'),
(4889, 163, 1, 'Точность'),
(4890, 164, 1, 'Работая с нами, вы можете быть уверенны, что такси будет подано точно в срок.'),
(4891, 165, 1, 'Комфорт'),
(4892, 166, 1, 'Мы ценим Ваш комфорт и по этому вы можете забыть о курящих водителях и неприятных запахов в салоне.'),
(4893, 167, 1, 'Бесплатное автокресло'),
(4894, 168, 1, 'Мы абсолютно бесплатно предоставим автокресло для вашего ребенка.'),
(4895, 169, 1, 'Сервис'),
(4896, 170, 1, 'Наши водители всегда с радостью встретят Вас в аэропорту и помогут с вашим багажом.'),
(4897, 171, 1, 'Контакты <span>с нами</span>'),
(4898, 172, 1, 'Если остались вопросы напишите его в форме ниже.'),
(8529, 103, 2, 'Такси из аэропорта Симферополя в [city_2_vin] тел. для заказа [phone]. Сколько стоит такси Симферополь - [city_2_im]. Недорогие тарифы. У нас вы можете заказать подачу автомобиля в любую точку Симферополя или [city_2_rod]. Быстро и безопасно - вот наш девиз!'),
(8530, 104, 2, 'Такси из Симферополя в [city_2_vin]. Стоимость от [min_price] руб'),
(8531, 105, 2, 'ТАКСИ СИМФЕРОПОЛЬ [city_2_im]'),
(8532, 106, 2, 'НАДЕЖНОЕ И ДОСТУПНОЕ ТАКСИ  ИЗ СИМФЕРОПОЛЯ В [city_2_vin] ПО ЦЕНЕ НА 25% НИЖЕ РЫНОЧНЫХ. СПЕШИТЕ ЗАКАЗАТЬ ТАКСИ ПО НИЗКИМ ЦЕНАМ.'),
(8533, 107, 2, 'Посмотреть прайс лист'),
(8534, 108, 2, 'Заказать точный расчёт стоимости поездки'),
(8535, 109, 2, '<span>О нас</span>'),
(8536, 110, 2, 'НЕДОРОГОЕ ТАКСИ ИЗ СИМФЕРОПОЛЯ В [city_2_vin] И ПО КРЫМУ'),
(8537, 111, 2, 'Недорого закажите такси по Крыму из Симферополя'),
(8538, 112, 2, '<p>Заказать и узнать цену из Симферополя в [city_2_vin] и по Крыму можно по телефону [phone].  \r\nПоездки по Крыму в летний сезон особенно утомительные из-за загруженности дорог. Фирма\r\nгарантировано подаст такси в Симферополе или в [city_2_rod] в любой день. В автопарке насчитывается более 100\r\nтранспортных средств, поэтому клиент не столкнется с проблемой их отсутствия. Компания\r\nрегулярно проверяет профессионализм водителей. Они проходят повышение квалификации,\r\nпоэтому в их компетентности можно не сомневаться.</p>'),
(8539, 113, 2, '<p>Почему стоит заказывать такси Симферополь - [city_2_im] :</p>\r\n<p>1. Надежность. Клиент может позвонить в любое время суток. Диспетчер подберет нужный автомобиль с учетом всех пожеланий. На сайте есть специальная форма для предварительного бронирования, после заполнения которой, человек будет уверен в том, что по его приезду водитель приедет вовремя в назначенный день.</p>\r\n<p>2. Безопасность. Машины, которые находятся в автопарке, ежегодно проходят техническую\r\nпроверку. Мастера тщательно ищут неисправности, поэтому клиента встречает\r\nавтомобиль, соответствующий стандартам.</p>\r\n<p>3. Выбор оптимального маршрута <a href=\"[main_url]\" style=\"color:black\">такси из Симферополя в [city_2_vin].</a> Диспетчер подберет удачный путь в любую точку Крыма. Водитель всегда учитывает загруженность дорог, чтобы объезжать пробки.</p>\r\n<p>Стоимость фиксированная, поэтому никаких доплат за поездку не предвещается. Компания дает возможность аренды автомобиля на целый день по умеренной стоимости. Бесплатно предоставляется детское кресло для пассажиров с маленькими детьми. Его можно установить в машину любого класса. От водителя клиент не услышит грубость или\r\nнеприятный тон. Многочасовая дорога пройдет в комфортной атмосфере, при этом водитель всегда беспокоится о самочувствии пассажиров и останавливает машину по желанию человека.</p>'),
(8540, 114, 2, 'Тарифы такси из Симферополя <span>по Крыму</span>'),
