(8567, 145, 2, 'Любой из выбранных способов надежный. Диспетчер, в любое время суток может принять Ваш заказ по телефону и сразу забронировать автомобиль. При бронировании через форму заказа на сайте, менеджер в ближайшее время, после поступления вашего письма, ответит вам на ваш запрос. В обоих случаях, без автомобиля вы не останетесь. Сделать заказ можно в любое время. Мы рекомендуем забронировать такси за 1-2 суток поездки.'),
(8568, 146, 2, 'Такси из Симферополя отзывы'),
(8569, 147, 2, 'Светлана'),
(8570, 148, 2, 'Я очень довольна сервисом компании, по прилёту меня сразу же встретили с табличкой и помогли с багажом при этом без доплаты. Водитель был очень вежлив, а салон был чистым и с приятным легким запахом. Я доехала спокойно и с удовольствием. Всем рекомендую!'),
