(8572, 150, 2, 'Валентин'),
(8573, 151, 2, 'Заказывал через сайт такси бизнес класса за час до вылета. Не смотря на то что самолёт задержали меня ждали до последнего, встретили в самом у и мне не пришлось некого искать. Подали Toyota Camry со всеми удобствами и комфортом всё как полагается. Доехал я быстро и в приятной компании. Буду Вашим постоянным клиентом.'),
(8574, 152, 2, 'Такси из Симферополя в [city_2_vin] отзывы'),
(8575, 153, 2, 'Вячеслав'),
(8576, 154, 2, 'Пользуюсь услугами Вашего такси уже более 3-х лет по работе в командировке. Выбрав случайно один раз, оставив заявку на сайте и мне перезвонили буквально через 5 минут сориентировали по цене и другим вопросам. Ну и что скажу по сервису - встретили, помогли с багажом, приятные и тактичные водители. Теперь всегда пользуюсь их услугами так как всё устраивает. Советую данную компанию.'),
