(8580, 158, 2, '© Симферополь [year] [city_1_im]'),
(8581, 159, 2, 'Политика конфиденциальности и оферты'),
(8582, 160, 2, '<p>Нам очень важна конфиденциальность Вашей информации. Личные данные, которые Вы доверяете нам, заполняя форму заявки на нашем сайте, будут использованы с целью подготовки услуг в соответствии с Вашими основными требованиями и пожеланиями. Передача Вашей информации третьим лицам полностью исключена. Какие данные собираются на сайте: При добровольном заполнении формы заявки Вы отправляете нам: свое имя, телефон и E-mail. Наш сайт не является публичной офертой и носит исключительно информационный характер </p>'),
