(8598, 106, 3, 'НАДЕЖНОЕ И ДОСТУПНОЕ ТАКСИ ПО СТОИМОСТИ НА 20% НИЖЕ РЫНОЧНЫХ ЦЕН.'),
(8599, 107, 3, 'Посмотреть прайс лист'),
(8600, 108, 3, 'Заказать точный расчёт стоимости поездки'),
(8601, 109, 3, '<span>О нас</span>'),
(8602, 110, 3, 'НЕДОРОГОЕ ТАКСИ ИЗ [city_1_rod] В СИМФЕРОПОЛЬ И ПО КРЫМУ'),
(8603, 111, 3, 'Недорого закажите такси по Крыму из [city_1_rod]'),
(8604, 112, 3, '<p>Такси  из [city_1_rod]  в Симферополь и по Крыму заказать и узнать цену можно узнать по тел. [phone] или на официальном сайте. \r\nСпрос на поездки по Крыму высокий в любое время, особенно в курортный период. Часто,\r\nзаказывая такси [city_1_im] - Симферополь, клиент слышит, что свободных машин нет. Это неприятное\r\nобстоятельство срывает все планы. Обращаясь в компанию по перевозкам, человек может\r\nрассчитывать на быстрое и качественное обслуживание. Автопарк фирмы достаточно большой и\r\nразнообразный, поэтому заказать поездку можно от эконом класса до минибуса на 8 человек. На сайте\r\nесть вся актуальная информация о ценах и классах машин.</p>'),
(8605, 113, 3, '<p>Возможности компании для заказа такси [city_1_im] - Симферополь:</p>\r\n<p>1. Быстрое и качественное обслуживание. Фирма предоставляет возможность заказа на официальном сайте и с помощью телефонного звонка. Каждый выбирает удобный для себя способ, а диспетчер мгновенно реагирует на заявку независимо от выбранного метода заказа такси.</p>\r\n<p>2. Комфортные автомобили. Машины в автопарке рассчитаны даже на большое количество людей. Для компании из 8 человек приезжает просторный мини-бус. Также клиент может выбрать такси из [city_1_rod]  в Симферополь на любой кошелек. Есть более дешевые и дорогие варианты (эконом, комфорт, бизнес).</p>\r\n<p>3. Работаем в любое время суток. Скорость работы оператора и водителя не зависит от времени суток, в которое поступил заказ. Заявка будет обработана одинаково быстро как днем, так и ночью.</p>\r\n<p>4. Регулярные скидки. На официальном сайте указывается актуальная информация, в том числе и размер постоянных скидок. Сейчас действуют акции, помогающие значительно сэкономить средства. Детские кресла или ФЭСТ предоставляются бесплатно по необходимости.</p>\r\n<p>Машины компании порадуют клиента не только безопасностью, но и стильным видом, а также чистотой салона. <a href=\"[main_url]\" style=\"color:black\">Такси из [city_1_rod] в Симферополь</a> эконом класса по внешнему виду ненамного уступает бизнес классу, поэтому клиент с небольшим бюджетом с комфортом проведет поездку. Понравившийся автомобиль можно забронировать заранее. Он будет ожидать  клиента в назначенном\r\nместе и времени.</p>'),
