(8628, 140, 3, 'Откуда я могу узнать, какая будет машина и телефон водителя?'),
(8629, 141, 3, 'Перед поездкой на указанный вами номер телефона поступит СМС сообщение, где будет указана марка автомобиля, гос.номер, контактный телефон водителя. А также, в обязанности водителя входит то, что он должен сам созвониться с пассажирами после приземления самолета.'),
(8630, 142, 3, 'Та цена, которую мне сказали окончательная? Доплат не будет?'),
(8631, 143, 3, 'Стоимость проезда, которую вам озвучил диспетчер или указал менеджер в письме фиксированная. Доплата, может быть, только в случае существенного изменения вашего маршрута.'),
(8632, 144, 3, 'Как надежнее: сделать заказ через форму заказа на сайте или по телефону? За какое время нужно заказать автомобиль?'),
(8633, 145, 3, 'Любой из выбранных способов надежный. Диспетчер, в любое время суток может принять Ваш заказ по телефону и сразу забронировать автомобиль. При бронировании через форму заказа на сайте, менеджер в ближайшее время, после поступления вашего письма, ответит вам на ваш запрос. В обоих случаях, без автомобиля вы не останетесь. Сделать заказ можно в любое время. Мы рекомендуем забронировать такси за 1-2 суток поездки.'),
(8634, 146, 3, 'Такси из [city_1_rod] отзывы'),
(8635, 147, 3, 'Светлана'),
(8636, 148, 3, 'Я очень довольна сервисом компании, по прилёту меня сразу же встретили в аэропорту Симферополя с табличкой и помогли с багажом при этом без доплаты. Водитель был очень вежлив, а салон был чистым и с приятным легким запахом. Я доехала спокойно и с удовольствием. Всем рекомендую!'),
(8637, 149, 3, 'Такси в Симферополь отзывы'),
(8638, 150, 3, 'Валентин'),
(8639, 151, 3, 'Заказывал через сайт такси бизнес класса за час до вылета. Не смотря на то что самолёт задержали меня ждали до последнего, встретили в самом аэропорту Симферополя и мне не пришлось некого искать. Подали Toyota Camry со всеми удобствами и комфортом всё как полагается. Доехал я быстро и в приятной компании. Буду Вашим постоянным клиентом.'),
(8640, 152, 3, 'Такси из [city_1_rod] в Симферополь отзывы'),
(8641, 153, 3, 'Вячеслав'),
(8642, 154, 3, 'Пользуюсь услугами Вашего такси уже более 3-х лет по работе в командировке. Выбрав случайно один раз, оставив заявку на сайте и мне перезвонили буквально через 5 минут сориентировали по цене и другим вопросам. Ну и что скажу по сервису - встретили, помогли с багажом, приятные и тактичные водители. Теперь всегда пользуюсь их услугами так как всё устраивает. Советую данную компанию.'),
(8643, 155, 3, 'О нас говорят <span>наши клиенты</span>'),
(8644, 156, 3, 'Описание'),
(8645, 157, 3, '<p>Такси в Симферополь онлайн.  Заказать и узнать цену из [city_1_rod] по Крыму можно узнать по телефону <nobr>[phone]</nobr></p>'),
(8646, 158, 3, '© [city_1_im] [year] Симферополь'),
(8647, 159, 3, 'Политика конфиденциальности и оферты'),
(8648, 160, 3, '<p>Нам очень важна конфиденциальность Вашей информации. Личные данные, которые Вы доверяете нам, заполняя форму заявки на нашем сайте, будут использованы с целью подготовки услуг в соответствии с Вашими основными требованиями и пожеланиями. Передача Вашей информации третьим лицам полностью исключена. Какие данные собираются на сайте: При добровольном заполнении формы заявки Вы отправляете нам: свое имя, телефон и E-mail. Наш сайт не является публичной офертой и носит исключительно информационный характер </p>'),
(8649, 161, 3, 'Такси По Крыму из [city_1_rod]'),
