(8661, 103, 4, 'Такси из [city_1_rod] в [city_2_vin] тел. для заказа [phone]. Сколько стоит такси [city_1_im] - [city_2_im]. Недорогие тарифы. У нас вы можете заказать подачу автомобиля в любую точку [city_1_rod] или [city_2_rod]. Быстро и безопасно - вот наш девиз!'),
