(8669, 111, 4, 'Недорого закажите такси по Крыму из [city_1_rod]'),
(8670, 112, 4, '<p>Заказать и узнать цену из [city_1_rod] в [city_2_vin] и по Крыму можно по телефону [phone].  \r\nПоездки по Крыму в летний сезон особенно утомительные из-за загруженности дорог. Фирма гарантировано подаст такси в [city_1_pred] или в [city_2_pred] в любой день. В автопарке насчитывается более 100 транспортных средств, поэтому клиент не столкнется с проблемой их отсутствия. Компания регулярно проверяет профессионализм водителей. Они проходят повышение квалификации, поэтому в их компетентности можно не сомневаться.</p>'),
(8671, 113, 4, '<p>Почему стоит заказывать такси [city_1_im] - [city_2_im] :</p>\r\n<p>1. Надежность. Клиент может позвонить в любое время суток. Диспетчер подберет нужный автомобиль с учетом всех пожеланий. На сайте есть специальная форма для предварительного бронирования, после заполнения которой, человек будет уверен в том, что по его приезду водитель приедет вовремя в назначенный день.</p>\r\n<p>2. Безопасность. Машины, которые находятся в автопарке, ежегодно проходят техническую проверку. Мастера тщательно ищут неисправности, поэтому клиента встречает автомобиль, соответствующий стандартам.</p>\r\n<p>3. Выбор оптимального маршрута <a href=\"[domain_url]\" style=\"color:black\">такси из [city_1_rod] в [city_2_vin].</a> Диспетчер подберет удачный путь в любую точку Крыма. Водитель всегда учитывает загруженность дорог, чтобы объезжать пробки.</p>\r\n<p>Стоимость фиксированная, поэтому никаких доплат за поездку не предвещается. Компания дает возможность аренды автомобиля на целый день по умеренной стоимости. Бесплатно предоставляется детское кресло для пассажиров с маленькими детьми. Его можно установить в машину любого класса. От водителя клиент не услышит грубость или\r\nнеприятный тон. Многочасовая дорога пройдет в комфортной атмосфере, при этом водитель всегда беспокоится о самочувствии пассажиров и останавливает машину по желанию человека.</p>'),
