(8701, 147, 4, 'Светлана'),
(8702, 148, 4, 'Я очень довольна сервисом компании, по прилёту меня сразу же встретили с табличкой и помогли с багажом при этом без доплаты. Водитель был очень вежлив, а салон был чистым и с приятным легким запахом. Я доехала спокойно и с удовольствием. Всем рекомендую!'),
