(8705, 151, 4, 'Заказывал через сайт такси бизнес класса за час до вылета. Не смотря на то что самолёт задержали меня ждали до последнего, встретили в самом у и мне не пришлось некого искать. Подали Toyota Camry со всеми удобствами и комфортом всё как полагается. Доехал я быстро и в приятной компании. Буду Вашим постоянным клиентом.'),
(8706, 152, 4, 'Такси из [city_1_rod] в [city_2_vin] отзывы'),
(8707, 153, 4, 'Вячеслав'),
(8708, 154, 4, 'Пользуюсь услугами Вашего такси уже более 3-х лет по работе в командировке. Выбрав случайно один раз, оставив заявку на сайте и мне перезвонили буквально через 5 минут сориентировали по цене и другим вопросам. Ну и что скажу по сервису - встретили, помогли с багажом, приятные и тактичные водители. Теперь всегда пользуюсь их услугами так как всё устраивает. Советую данную компанию.'),
(8709, 155, 4, 'О нас говорят <span>наши клиенты</span>'),
(8710, 156, 4, 'Описание'),
(8711, 157, 4, '<p>Такси в [city_2_vin] онлайн.  Заказать и узнать цену из [city_1_rod] по Крыму можно узнать по телефону [phone].</p>'),
(8712, 158, 4, '© [city_1_im] [year] [city_2_im]'),
(8713, 159, 4, 'Политика конфиденциальности и оферты'),
(8714, 160, 4, '<p>Нам очень важна конфиденциальность Вашей информации. Личные данные, которые Вы доверяете нам, заполняя форму заявки на нашем сайте, будут использованы с целью подготовки услуг в соответствии с Вашими основными требованиями и пожеланиями. Передача Вашей информации третьим лицам полностью исключена. Какие данные собираются на сайте: При добровольном заполнении формы заявки Вы отправляете нам: свое имя, телефон и E-mail. Наш сайт не является публичной офертой и носит исключительно информационный характер </p>'),
(8715, 161, 4, 'Такси По Крыму из [city_1_rod]'),
(8716, 162, 4, 'читать подробнее'),
(8717, 163, 4, 'Точность'),
(8718, 164, 4, 'Работая с нами, вы можете быть уверенны, что такси будет подано точно в срок.'),
(8719, 165, 4, 'Комфорт'),
(8720, 166, 4, 'Мы ценим Ваш комфорт и по этому вы можете забыть о курящих водителях и неприятных запахов в салоне.'),
(8721, 167, 4, 'Бесплатное автокресло'),
(8722, 168, 4, 'Мы абсолютно бесплатно предоставим автокресло для вашего ребенка.'),
(8723, 169, 4, 'Сервис'),
(8724, 170, 4, 'Наши водители всегда с радостью встретят Вас в аэропорту и помогут с вашим багажом.'),
(8725, 171, 4, 'Контакты <span>с нами</span>'),
(8726, 172, 4, 'Если остались вопросы напишите его в форме ниже.'),
(8727, 103, 5, 'Трансфер из [city_1_rod] в [city_2_vin] и  по Крыму недорого заказ'),
(8728, 104, 5, 'Трансфер из [city_1_rod] в [city_2_vin] и по Крыму от [min_price] руб'),
(8729, 105, 5, 'Трансфер ИЗ [city_1_rod] ПО КРЫМУ И В [city_2_vin]'),
(8730, 106, 5, 'НАДЕЖНЫЙ И ДОСТУПНЫЙ ТРАНСФЕР ПО ЦЕНЕ НА 25% НИЖЕ РЫНОЧНЫХ'),
(8731, 107, 5, 'Посмотреть прайс лист'),
(8732, 108, 5, 'Заказать точный расчёт стоимости поездки'),
(8733, 109, 5, '<span>О нас</span>'),
(8734, 110, 5, 'НЕДОРОГОЙ ТРАНСФЕР ИЗ [city_1_rod] В [city_2_vin] И ПО КРЫМУ'),
(8735, 111, 5, 'Недорого закажите трансфер по Крыму из [city_2_rod]'),
(8736, 112, 5, '<p>Трансфер [city_1_im] - [city_2_im] является одной из самых популярных услуг, используемых в Крыму. После прибытия в аэропорт больше не нужно долго ждать такси, ведь водитель уже будет ожидать в нужное время. Компания проверена многолетним опытом в перевозках и большим количеством довольных клиентов. На сайте есть отзывы, свидетельствующие о надежности и высоком качестве работы службы. </p>\r\n<p> Больше не нужно искать подходящее такси, ведь даже для большой компании с объемным багажом найдется просторный минивен, в котором поездка пройдет незаметно. Услуги, предоставляемые компанией, понравятся людям, ценящим экономию и свое время. Заказав машину представительского класса, можно любоваться окрестностями Крыма во время длительного маршрута. </p> \r\n\r\n<p><strong>Почему следует заказывать трансфер из [city_1_rod] в [city_2_vin]</strong></p>'),
(8737, 113, 5, '<ul>\r\n<li>Выгодные тарифы. На самые по популярные маршруты регулярно проводятся скидки и акции, о которых можно узнать у диспетчера или на сайте. На главной странице указана фиксированная стоимость, а скрытые платежи не предусматриваются компанией. </li>\r\n<li>Большой выбор автомобилей. В автопарке есть различные классы, начиная от эконома и заканчивая бизнесом. Самыми популярными транспортными средствами являются Мерседес S класса, Мерседес Е -212, Мерседес Виана, Тойота Камри, среди которых есть и VIP трансфер. </li>\r\n<li>Безопасность поездки достигается профессионализмом водителей. Все автомобили компании не старше 7 лет и проходят технический осмотр на неисправности. Водители имеют большой стаж работы. Они выбирают оптимальный маршрут и легко объезжают пробки. </li>\r\n<li>Доступность онлайн заказов. На официальном сайте клиент может заполнить быструю форму, которую диспетчер мгновенно обработает и пришлет автомобиль в указанное место. \r\n</ul>\r\n<p>У нас вы можете недорого произвести  \r\n<a href=\"[direction_url]\" style=\"color:black\">заказ такси [city_1_im] - [city_2_im] </a>\r\n</p>'),
(8738, 114, 5, 'Тарифы на трансфер из [city_1_rod] <span>по Крыму</span>'),
(8739, 115, 5, 'Посмотрите стоимость проезда из [city_1_rod] по основным городам Крыма в [year] году'),
(8740, 116, 5, 'Акция ограничена количеством автомобилей. Спешите заказать <a href=\"[domain_url]\">трансфер  из [city_1_rod]</a>'),
(8741, 117, 5, 'ВЫБЕРИТЕ КЛАСС <span>АВТО</span>'),
(8742, 118, 5, 'Для вашего удобства мы предлагаем 4 класса транспортных средств.'),
(8743, 119, 5, 'Эконом трансфер [city_1_im] - [city_2_im]'),
(8744, 120, 5, 'Трансфер класса комфорт [city_1_im] - [city_2_im]'),
(8745, 121, 5, 'Бизнес трансфер [city_1_im] - [city_2_im]'),
(8746, 122, 5, 'Минивэн трансфер [city_1_im] - [city_2_im]'),
(8747, 123, 5, 'Наш <span>Сервис</span>'),
(8748, 128, 5, 'Водителя в штате'),
(8749, 129, 5, '83'),
(8750, 130, 5, 'Автомобилей в автопарке'),
(8751, 131, 5, '78'),
(8752, 132, 5, 'Выполненных заказов'),
(8753, 133, 5, '3004'),
(8754, 134, 5, 'Постоянных клиентов'),
(8755, 135, 5, '156'),
(8756, 136, 5, 'Ч. <span>A.</span> В. О.'),
(8757, 137, 5, 'Часто задаваемые вопросы наших клиентов.'),
(8758, 138, 5, 'Время отъезда изменилось, что делать?'),
(8759, 139, 5, 'В случае изменения времени отъезда, вам необходимо дополнительно сообщить об этом диспетчеру нашей компании. Подача автомобиля будет скорректирована с учетом реального времени'),
(8760, 140, 5, 'Откуда я могу узнать, какая будет машина и телефон водителя?'),
(8761, 141, 5, 'Перед поездкой на указанный вами номер телефона поступит СМС сообщение, где будет указана марка автомобиля, гос.номер, контактный телефон водителя. А также, в обязанности водителя трансфера входит то, что он должен сам созвониться с пассажирами перед поездкой'),
(8762, 142, 5, 'Та цена, которую мне сказали окончательная? Доплат не будет?'),
(8763, 143, 5, 'Стоимость проезда, которую вам озвучил диспетчер или указал менеджер в письме фиксированная. Доплата, может быть, только в случае существенного изменения вашего маршрута.'),
(8764, 144, 5, 'Как надежнее: сделать заказ трансфера через форму заказа на сайте или по телефону? За какое время нужно заказать автомобиль?'),
(8765, 145, 5, 'Любой из выбранных способов надежный. Диспетчер, в любое время суток может принять Ваш заказ по телефону и сразу забронировать автомобиль. При бронировании через форму заказа на сайте, менеджер в ближайшее время, после поступления вашего письма, ответит вам на ваш запрос. В обоих случаях, без автомобиля вы не останетесь. Сделать заказ трансфера можно в любое время. Мы рекомендуем забронировать авто за 1-2 суток поездки.'),
(8766, 146, 5, 'трансфер из [city_1_rod] отзывы'),
(8767, 147, 5, 'Светлана'),
(8768, 148, 5, 'Мы приехали в [city_1_vin] и полдня провели в поисках такси (ехать нужно было в [city_2_vin]). В итоге поехали с водителем, который обгонял «не глядя». А обратно заказали трансфер. Водитель аккуратно вел. Закажем еще раз.'),
(8769, 149, 5, 'Трансфер в [city_2_vin] отзывы'),
(8770, 150, 5, 'Валентин'),
(8771, 151, 5, 'Заказывал трансфер бизнес класса за час до отъезда. Не смотря на то что, поездка перенесласлась еще на час, меня ждали до последнего, встретили и мне не пришлось никого искать. Подали Toyota Camry со всеми удобствами и комфортом всё как полагается. Доехал я быстро и в приятной компании. Буду Вашим постоянным клиентом.'),
(8772, 152, 5, 'Трансфер из [city_1_rod] в [city_2_vin] отзывы'),
(8773, 153, 5, 'Вячеслав'),
(8774, 154, 5, 'Отправлял сына-подростка в санаторий [city_2_rod]. Выезд был из города [city_1_rod]. Волновались за него, но по дороге ребенок звонил и рассказывал, что все хорошо. Водитель даже помог ему с сумками по приезде.'),
(8775, 155, 5, 'О нас говорят <span>наши клиенты</span>'),
(8776, 156, 5, 'Описание'),
(8777, 157, 5, '<p>Трансфер в [city_2_vin] онлайн.  Заказать и узнать цену из [city_1_rod] по Крыму можно узнать по телефону <nobr>[phone]</nobr></p>'),
(8778, 158, 5, '© [city_1_im] [year] [city_2_im]'),
(8779, 159, 5, 'Политика конфиденциальности и оферты'),
(8780, 160, 5, '<p>Нам очень важна конфиденциальность Вашей информации. Личные данные, которые Вы доверяете нам, заполняя форму заявки на нашем сайте, будут использованы с целью подготовки услуг в соответствии с Вашими основными требованиями и пожеланиями. Передача Вашей информации третьим лицам полностью исключена. Какие данные собираются на сайте: При добровольном заполнении формы заявки Вы отправляете нам: свое имя, телефон и E-mail. Наш сайт не является публичной офертой и носит исключительно информационный характер </p>'),
(8781, 161, 5, 'Трансфер По Крыму из Ялты'),
(8782, 162, 5, 'читать подробнее'),
(8783, 163, 5, 'Точность'),
(8784, 164, 5, 'Работая с нами, вы можете быть уверенны, что трансфер будет подано точно в срок.'),
(8785, 165, 5, 'Комфорт'),
(8786, 166, 5, 'Мы ценим Ваш комфорт и по этому вы можете забыть о курящих водителях и неприятных запахов в салоне.'),
(8787, 167, 5, 'Бесплатное автокресло'),
(8788, 168, 5, 'Мы абсолютно бесплатно предоставим автокресло для вашего ребенка.'),
(8789, 169, 5, 'Сервис'),
(8790, 170, 5, 'Наши водители всегда с радостью встретят Вас в аэропорту и помогут с вашим багажом.'),
(8791, 171, 5, 'Контакты <span>с нами</span>'),
